package com.ridelink.farepayment.domain; import java.math.BigDecimal; import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document("payments") public class Payment {@Id private String id;private String rideId,fareId,method;private BigDecimal amount;private PaymentStatus status;private Instant recordedAt;public String getId(){return id;}public void setId(String v){id=v;}public String getRideId(){return rideId;}public void setRideId(String v){rideId=v;}public String getFareId(){return fareId;}public void setFareId(String v){fareId=v;}public String getMethod(){return method;}public void setMethod(String v){method=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public PaymentStatus getStatus(){return status;}public void setStatus(PaymentStatus v){status=v;}public Instant getRecordedAt(){return recordedAt;}public void setRecordedAt(Instant v){recordedAt=v;}}
